#!/bin/bash
set -e
echo '[pathctl] install: writing project files'

cat > package.json << 'EOF'
{
  "name": "rdk-path-control",
  "version": "1.0.0",
  "description": "RDK SD-WAN path control over IoT Core",
  "main": "index.js",
  "license": "ISC"
}
EOF

cat > index.js << 'EOF'
const axios = require('axios');
const sdk = require('aws-iot-device-sdk-v2');
const ipc = sdk.greengrasscoreipc;
const { mqtt } = sdk;

// Topic prefix + local API are injected by the Run lifecycle as env vars so
// the same artifact serves both gateway families (rdk for Plano, prpl for
// McKinney) by only changing the deployment-time component configuration.
const PREFIX        = process.env.PATHCTL_TOPIC_PREFIX || 'rdk';
const LOCAL_API     = process.env.PATHCTL_LOCAL_API   || 'http://127.0.0.1:8090/api/path';
const CONTROL_TOPIC = PREFIX + '/path/control';
const RESULT_TOPIC  = PREFIX + '/path/control/result';
const VALID_MODES   = ['auto', 'fiber', '5g'];

async function main() {
  const client = ipc.createClient();
  await client.connect();
  console.log('[pathctl] IPC connected; control=' + CONTROL_TOPIC + ' result=' + RESULT_TOPIC);

  const publishResult = async (body) => {
    const payload = Buffer.from(JSON.stringify({ ...body, ts: Date.now() }));
    try {
      await client.publishToIoTCore({ topicName: RESULT_TOPIC, qos: mqtt.QoS.AtLeastOnce, payload });
      console.log('[pathctl] result published:', JSON.stringify(body));
    } catch (e) {
      console.error('[pathctl] publish failed:', e && e.message);
    }
  };

  const handler = {
    onStreamEvent: async (event) => {
      const raw = Buffer.from(event.message.payload).toString('utf-8');
      console.log('[pathctl] command received:', raw);
      let mode, id;
      try { const p = JSON.parse(raw); mode = p.mode; id = p.id; }
      catch { await publishResult({ ok: false, error: 'invalid JSON payload' }); return; }
      if (!VALID_MODES.includes(mode)) {
        await publishResult({ id, ok: false, error: 'mode must be one of auto|fiber|5g', got: mode });
        return;
      }
      try {
        const res = await axios.post(LOCAL_API, { mode }, { timeout: 5000, headers: { 'Content-Type': 'application/json' } });
        await publishResult({ id, ok: true, mode, httpStatus: res.status });
      } catch (e) {
        const status = e && e.response ? e.response.status : null;
        await publishResult({ id, ok: false, mode, httpStatus: status, error: e && e.message });
      }
    },
    onStreamError: (e) => { console.error('[pathctl] stream error:', e && e.message); return false; },
    onStreamClosed: () => { console.log('[pathctl] stream closed'); },
  };

  await client.subscribeToIoTCore({ topicName: CONTROL_TOPIC, qos: mqtt.QoS.AtLeastOnce }, handler);
  console.log('[pathctl] subscribed; waiting for commands');

  // Keep the event loop alive for the lifetime of the component.
  setInterval(() => {}, 1 << 30);
}

main().catch((e) => { console.error('[pathctl] fatal:', e); process.exit(1); });
EOF

echo '[pathctl] install: npm install'
npm install axios aws-iot-device-sdk-v2 --cache /tmp/npm-cache --omit=dev
echo '[pathctl] install: done'
